export const AIVX_SHARE_BLOCK: string = "  <div class=\"share-toast\" role=\"status\" aria-live=\"polite\"></div>\n  <script>\n  (function() {\n    const btn = document.querySelector('.share-btn');\n    const toast = document.querySelector('.share-toast');\n    if (!btn || !toast) return;\n\n    const labelEl = btn.querySelector('.share-btn-label');\n    const originalLabel = labelEl ? labelEl.textContent : 'Share Report';\n    let btnTimer = null, toastTimer = null;\n\n    function getShareUrl() {\n      const canonical = document.querySelector('link[rel=\"canonical\"]');\n      if (canonical && canonical.href) return canonical.href;\n      return window.location.href;\n    }\n\n    function showToast(msg) {\n      toast.textContent = msg;\n      toast.classList.add('visible');\n      clearTimeout(toastTimer);\n      toastTimer = setTimeout(function() { toast.classList.remove('visible'); }, 2200);\n    }\n\n    function flashButton() {\n      if (labelEl) labelEl.textContent = 'Copied!';\n      btn.classList.add('copied');\n      clearTimeout(btnTimer);\n      btnTimer = setTimeout(function() {\n        if (labelEl) labelEl.textContent = originalLabel;\n        btn.classList.remove('copied');\n      }, 2000);\n    }\n\n    async function copyToClipboard(text) {\n      if (navigator.clipboard && window.isSecureContext) {\n        try { await navigator.clipboard.writeText(text); return true; } catch (e) {}\n      }\n      const ta = document.createElement('textarea');\n      ta.value = text;\n      ta.setAttribute('readonly', '');\n      ta.style.cssText = 'position:fixed;top:0;left:0;opacity:0;pointer-events:none;';\n      document.body.appendChild(ta);\n      ta.select();\n      let ok = false;\n      try { ok = document.execCommand('copy'); } catch (e) {}\n      document.body.removeChild(ta);\n      return ok;\n    }\n\n    btn.addEventListener('click', async function() {\n      const url = getShareUrl();\n      const ok = await copyToClipboard(url);\n      if (ok) { flashButton(); showToast('Link copied to clipboard'); }\n      else { showToast('Copy failed. Please copy: ' + url); }\n    });\n  })();\n  </script>\n"
